# X++ Script to Create a Custom REST Service in Dynamics AX

Here's a comprehensive example of creating a custom REST service in Dynamics AX (D365 Finance & Operations):

## 1. Create a Data Contract Class

```xpp
[DataContractAttribute]
public class MyCustomDataContract
{
    str customerAccount;
    str customerName;
    real creditLimit;

    [DataMemberAttribute('CustomerAccount')]
    public str parmCustomerAccount(str _customerAccount = customerAccount)
    {
        customerAccount = _customerAccount;
        return customerAccount;
    }

    [DataMemberAttribute('CustomerName')]
    public str parmCustomerName(str _customerName = customerName)
    {
        customerName = _customerName;
        return customerName;
    }

    [DataMemberAttribute('CreditLimit')]
    public real parmCreditLimit(real _creditLimit = creditLimit)
    {
        creditLimit = _creditLimit;
        return creditLimit;
    }
}
```

## 2. Create a Response Data Contract Class

```xpp
[DataContractAttribute]
public class MyCustomResponseContract
{
    boolean success;
    str message;
    str errorDetails;

    [DataMemberAttribute('Success')]
    public boolean parmSuccess(boolean _success = success)
    {
        success = _success;
        return success;
    }

    [DataMemberAttribute('Message')]
    public str parmMessage(str _message = message)
    {
        message = _message;
        return message;
    }

    [DataMemberAttribute('ErrorDetails')]
    public str parmErrorDetails(str _errorDetails = errorDetails)
    {
        errorDetails = _errorDetails;
        return errorDetails;
    }
}
```

## 3. Create the Service Class

```xpp
[SysOperationServiceAttribute('MyCustomService')]
class MyCustomService
{
    // GET Method - Retrieve Customer Information
    [SysOperationMethodAttribute('Get Customer', 'Get customer details by account number')]
    public MyCustomDataContract getCustomer(str _customerAccount)
    {
        MyCustomDataContract response = new MyCustomDataContract();
        CustTable custTable;

        try
        {
            select firstOnly custTable
                where custTable.AccountNum == _customerAccount;

            if (custTable)
            {
                response.parmCustomerAccount(custTable.AccountNum);
                response.parmCustomerName(custTable.name());
                response.parmCreditLimit(custTable.CreditMax);
            }
        }
        catch (Exception::Error)
        {
            throw error("Error retrieving customer information");
        }

        return response;
    }

    // POST Method - Create or Update Customer
    [SysOperationMethodAttribute('Create or Update Customer', 'Creates or updates customer record')]
    public MyCustomResponseContract createOrUpdateCustomer(MyCustomDataContract _request)
    {
        MyCustomResponseContract response = new MyCustomResponseContract();
        CustTable custTable;

        try
        {
            ttsbegin;

            select forUpdate custTable
                where custTable.AccountNum == _request.parmCustomerAccount();

            if (!custTable)
            {
                // Create new customer
                custTable.clear();
                custTable.AccountNum = _request.parmCustomerAccount();
                custTable.CustGroup = 'DEFAULT'; // Set default group
            }

            // Update fields
            custTable.Name = _request.parmCustomerName();
            custTable.CreditMax = _request.parmCreditLimit();

            if (custTable.RecId == 0)
            {
                custTable.insert();
                response.parmMessage('Customer created successfully');
            }
            else
            {
                custTable.update();
                response.parmMessage('Customer updated successfully');
            }

            response.parmSuccess(true);

            ttscommit;
        }
        catch (Exception::Error)
        {
            response.parmSuccess(false);
            response.parmMessage('Error processing customer');
            response.parmErrorDetails(AifUtil::getClrErrorMessage());
        }

        return response;
    }

    // GET Method - Get Multiple Customers
    [SysOperationMethodAttribute('Get Customers List', 'Retrieve list of customers')]
    public List getCustomersList(str _custGroup = '')
    {
        List customerList = new List(Types::Class);
        CustTable custTable;
        MyCustomDataContract contract;

        try
        {
            while select custTable
                where (_custGroup == '' || custTable.CustGroup == _custGroup)
            {
                contract = new MyCustomDataContract();
                contract.parmCustomerAccount(custTable.AccountNum);
                contract.parmCustomerName(custTable.name());
                contract.parmCreditLimit(custTable.CreditMax);

                customerList.addEnd(contract);
            }
        }
        catch (Exception::Error)
        {
            throw error("Error retrieving customer list");
        }

        return customerList;
    }

    // DELETE Method - Delete Customer
    [SysOperationMethodAttribute('Delete Customer', 'Deletes a customer record')]
    public MyCustomResponseContract deleteCustomer(str _customerAccount)
    {
        MyCustomResponseContract response = new MyCustomResponseContract();
        CustTable custTable;

        try
        {
            ttsbegin;

            select forUpdate custTable
                where custTable.AccountNum == _customerAccount;

            if (custTable)
            {
                custTable.delete();
                response.parmSuccess(true);
                response.parmMessage('Customer deleted successfully');
            }
            else
            {
                response.parmSuccess(false);
                response.parmMessage('Customer not found');
            }

            ttscommit;
        }
        catch (Exception::Error)
        {
            response.parmSuccess(false);
            response.parmMessage('Error deleting customer');
            response.parmErrorDetails(AifUtil::getClrErrorMessage());
        }

        return response;
    }
}
```

## 4. Create a Service Group (AOT Configuration)

### Steps to register the service:

1. **In Visual Studio / AOT:**
   - Create a new **Service** item
   - Name it: `MyCustomService`
   - Set the Class property to: `MyCustomService`

2. **Add Operations:**
   - Right-click on the Service → Add Operation
   - Add each method from your service class

3. **Create Service Group:**
   - Create new **Service Group**
   - Name it: `MyCustomServiceGroup`
   - Add your service to the service group
   - Set **AutoDeploy** to `Yes`

## 5. Controller Class (Optional - for custom logic)

```xpp
class MyCustomServiceController extends SysOperationServiceController
{
    public static void main(Args _args)
    {
        MyCustomServiceController controller;

        controller = new MyCustomServiceController();
        controller.parmClassName(classStr(MyCustomService));
        controller.parmMethodName(methodStr(MyCustomService, getCustomer));
        controller.startOperation();
    }
}
```

## 6. Testing the REST Service

### PowerShell Example:

```powershell
# Set variables
$tenantId = "your-tenant-id"
$clientId = "your-client-id"
$clientSecret = "your-client-secret"
$resource = "https://your-environment.operations.dynamics.com"
$serviceUrl = "$resource/api/services/MyCustomServiceGroup/MyCustomService"

# Get OAuth token
$tokenEndpoint = "https://login.microsoftonline.com/$tenantId/oauth2/token"
$body = @{
    grant_type    = "client_credentials"
    client_id     = $clientId
    client_secret = $clientSecret
    resource      = $resource
}

$tokenResponse = Invoke-RestMethod -Method Post -Uri $tokenEndpoint -Body $body
$token = $tokenResponse.access_token

# Call the service - GET
$headers = @{
    "Authorization" = "Bearer $token"
    "Content-Type"  = "application/json"
}

$getUrl = "$serviceUrl/getCustomer?_customerAccount='US-001'"
$response = Invoke-RestMethod -Method Get -Uri $getUrl -Headers $headers

# Call the service - POST
$postBody = @{
    CustomerAccount = "US-001"
    CustomerName    = "Test Customer"
    CreditLimit     = 10000.00
} | ConvertTo-Json

$postResponse = Invoke-RestMethod -Method Post -Uri "$serviceUrl/createOrUpdateCustomer" -Headers $headers -Body $postBody
```

## 7. Security Configuration

```xpp
// Add to service class or create separate security class
[SysEntryPointAttribute(true)]
public MyCustomResponseContract createOrUpdateCustomer(MyCustomDataContract _request)
{
    // Method implementation
}
```

## Additional Notes:

1. **Build and Deploy**: After creating the service, build your project and synchronize the database
2. **Service Endpoint**: The service will be available at: `https://[environment].operations.dynamics.com/api/services/[ServiceGroup]/[Service]/[Method]`
3. **Authentication**: Use OAuth 2.0 with Azure AD for authentication
4. **Error Handling**: Always implement proper try-catch blocks and return meaningful error messages
5. **Performance**: Consider using set-based operations for bulk data handling

This creates a fully functional REST service in Dynamics AX/D365 F&O that can be consumed by external applications!

